import React, { useState, useEffect } from 'react';
import { PipelineUI } from './ui';
import { useStore } from './store';

function App() {
  const [result, setResult] = useState(null);

  // Initialize with one node on mount
  useEffect(() => {
    const { addNode, getNodeID } = useStore.getState();
    const nodeID = getNodeID('text');
    addNode({
      id: nodeID,
      type: 'text',
      position: { x: 100, y: 100 },
      data: { id: nodeID, nodeType: 'text' },
    });
  }, []);

  const handleSubmit = async () => {
    try {
      const { nodes, edges } = useStore.getState();
      const response = await fetch('http://localhost:8000/pipelines/parse', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes, edges }),
      });

      if (!response.ok) throw new Error('Network response was not ok');

      const result = await response.json();
      setResult(result);
      setTimeout(() => setResult(null), 5000);
    } catch (error) {
      alert('Failed to validate pipeline. Check console.');
    }
  };

  return (
    <div className="relative">
      <button
        onClick={handleSubmit}
        className="absolute top-4 right-4 px-4 py-2 bg-purple-600 text-white rounded z-10"
      >
        Submit Pipeline
      </button>

      {result && (
        <div className="absolute top-16 right-4 bg-white p-4 rounded-lg shadow-lg border-l-4 border-green-500 z-20">
          <div>Nodes: {result.num_nodes}</div>
          <div>Edges: {result.num_edges}</div>
          <div>DAG: {result.is_dag ? '✅ Yes' : '❌ No'}</div>
        </div>
      )}

      <PipelineUI />
    </div>
  );
}

export default App;
